        X = symbols("%s:%s" % (X, n))

    if isinstance(Y, string_types):
        Y = symbols("%s:%s" % (Y, n))

    coeffs = []

    for i in range(n):
        numer = Mul(*[(x - X[j]) for j in range(n) if j != i])
        denom = Mul(*[(X[i] - X[j]) for j in range(n) if i != j])
        coeffs.append(numer/denom)

